package com.nimbusbill.customer.entity;
import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="pricing_plan_versions") public class PricingPlanVersion{
 @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(optional=false) @JoinColumn(name="plan_id") private PricingPlan plan; @Column(name="version_number",nullable=false) private int versionNumber; @Column(nullable=false,length=3) private String currency; @Column(name="effective_from",nullable=false) private LocalDate effectiveFrom; @Column(name="effective_to") private LocalDate effectiveTo; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) private PricingVersionStatus status; @Column(name="created_by",nullable=false,length=150) private String createdBy; @Column(name="approved_by",length=150) private String approvedBy; @Column(name="created_at",nullable=false) private Instant createdAt; @Column(name="approved_at") private Instant approvedAt;
 @OneToMany(mappedBy="version",cascade=CascadeType.ALL,orphanRemoval=true) @OrderBy("priority ASC") private List<PricingRule> rules=new ArrayList<>(); @PrePersist void create(){if(createdAt==null)createdAt=Instant.now();if(status==null)status=PricingVersionStatus.DRAFT;}
 public UUID getId(){return id;} public PricingPlan getPlan(){return plan;} public void setPlan(PricingPlan v){plan=v;} public int getVersionNumber(){return versionNumber;} public void setVersionNumber(int v){versionNumber=v;} public String getCurrency(){return currency;} public void setCurrency(String v){currency=v;} public LocalDate getEffectiveFrom(){return effectiveFrom;} public void setEffectiveFrom(LocalDate v){effectiveFrom=v;} public LocalDate getEffectiveTo(){return effectiveTo;} public void setEffectiveTo(LocalDate v){effectiveTo=v;} public PricingVersionStatus getStatus(){return status;} public void setStatus(PricingVersionStatus v){status=v;} public String getCreatedBy(){return createdBy;} public void setCreatedBy(String v){createdBy=v;} public String getApprovedBy(){return approvedBy;} public void setApprovedBy(String v){approvedBy=v;} public Instant getCreatedAt(){return createdAt;} public Instant getApprovedAt(){return approvedAt;} public void setApprovedAt(Instant v){approvedAt=v;} public List<PricingRule> getRules(){return rules;}
}
